import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { sampleBytes } from '../../scripts/fixtures';
import { computePlan } from '../../src/engine/compute';
import type { Workbook } from '../../src/excel/exceljs';
import { findSheet } from '../../src/excel/schema';
import { scanFile } from '../../src/excel/unsupported';
import { bare, fixture, read, save, taskCell, tasksSheet } from './helpers';

// Files saved by Excel 365 (not regenerated by `npm run sample`). excel-saved.xlsx is the sample after a user
// edited it in Excel: added task 26 (with a new assignee), filled task 3's row yellow, added a hyperlink to
// task 2's remark, a note on B10, a conditional format on Variance and a "Cost code" column.
// excel-chart.xlsx is the sample with a chart sheet.
const wb = await fixture('excel-saved.xlsx');
const first = read(wb);
// Present at runtime, missing from ExcelJS's typings.
const conditionalFormats = (book: Workbook) => (tasksSheet(book) as unknown as { conditionalFormattings: unknown[] }).conditionalFormattings;

describe('a workbook saved by Excel', () => {
  it('reads the user edits', () => {
    const result = computePlan(first.plan);
    expect(first.plan.tasks).toHaveLength(26);
    expect(first.plan.tasks.at(-1)).toMatchObject({ id: 26, name: 'Final walkdown', assigned: ['ACME', 'NewCo'], predecessorsText: '25' });
    expect(first.plan.tasks[1]).toMatchObject({ remarks: 'Permit link', extra: {} });
    expect(first.plan.tasks[0]?.extra).toEqual({ Area: 'Initial work', 'Cost code': 'CC-100' });
    expect([...first.issues, ...result.issues].map((i) => i.message)).toEqual(['Added "NewCo" to Resources']);
  });

  it('keeps its formatting, hyperlink, note and conditional format through a save', async () => {
    const saved = await save(wb, first);
    expect(taskCell(saved, 4, 'name').fill).toMatchObject({ pattern: 'solid', fgColor: { argb: 'FFFFFF00' } });
    expect(taskCell(saved, 5, 'name').fill).toBeUndefined();
    expect(taskCell(saved, 3, 'remarks').value).toEqual({ text: 'Permit link', hyperlink: 'https://example.com/permit' });
    expect(taskCell(saved, 10, 'name').note).toMatchObject({ texts: [expect.objectContaining({ text: expect.stringContaining('Check with QC') as string })] });
    expect(conditionalFormats(saved)).toEqual(conditionalFormats(await fixture('excel-saved.xlsx')));
    expect(tasksSheet(saved).getCell('T2')).toMatchObject({ value: 'CC-100', font: expect.objectContaining({ bold: true }) as object });
    expect(findSheet(saved, 'Resources')!.getSheetValues().at(-1)).toEqual([undefined, 'NewCo', undefined, '#475569']);
    const again = bare(read(saved).plan.tasks);
    const before = bare(first.plan.tasks);
    expect(again.slice(0, 25)).toEqual(before.slice(0, 25));
    expect(again[25]).toEqual({ ...before[25], plannedStart: '2026-10-16', plannedFinish: '2026-10-16' }); // filled on save
  });
});

describe('content ExcelJS would drop', () => {
  it('finds the chart sheet in an Excel file, and nothing in the sample or the Excel-saved file', async () => {
    const bytes = (name: string) => new Uint8Array(readFileSync(join(import.meta.dirname, '../fixtures', name)));
    expect((await scanFile(bytes('excel-chart.xlsx'))).unsupported).toEqual(['charts']);
    expect(await scanFile(bytes('excel-saved.xlsx'))).toEqual({ unsupported: [], filtered: [] });
    expect((await scanFile(await sampleBytes())).unsupported).toEqual([]);
  });

  it('ExcelJS really drops it on save', async () => {
    const chart = await fixture('excel-chart.xlsx');
    expect(chart.worksheets.map((ws) => ws.name)).toEqual(['Project', 'Tasks', 'Resources', 'Holidays', 'Read Me']); // no chart sheet
  });
});
